-- RunIQ schema (SQLite dialect; generated by scripts/export_sql.py)

CREATE TABLE api_sync_log (
	log_id INTEGER NOT NULL, 
	endpoint VARCHAR(120) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	records_processed INTEGER NOT NULL, 
	message VARCHAR(400), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (log_id)
);


CREATE TABLE ranking_snapshots (
	snapshot_id INTEGER NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	match_format VARCHAR(10) NOT NULL, 
	gender VARCHAR(6) NOT NULL, 
	rank_pos INTEGER, 
	name VARCHAR(120) NOT NULL, 
	country VARCHAR(80), 
	rating INTEGER, 
	points INTEGER, 
	fetched_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (snapshot_id)
);

CREATE INDEX ix_rankings_lookup ON ranking_snapshots (category, match_format, gender);

CREATE TABLE series (
	series_id INTEGER NOT NULL, 
	series_name VARCHAR(200) NOT NULL, 
	season VARCHAR(20), 
	gender VARCHAR(6) NOT NULL, 
	host_country VARCHAR(80), 
	match_type VARCHAR(10) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	total_matches INTEGER, 
	api_series_id INTEGER, 
	PRIMARY KEY (series_id), 
	CONSTRAINT uq_series_name_gender_type UNIQUE (series_name, gender, match_type), 
	CONSTRAINT ck_series_type CHECK (match_type IN ('Test', 'ODI', 'T20I')), 
	CONSTRAINT ck_series_gender CHECK (gender IN ('male', 'female'))
);

CREATE INDEX ix_series_start_date ON series (start_date);

CREATE TABLE teams (
	team_id INTEGER NOT NULL, 
	team_name VARCHAR(80) NOT NULL, 
	gender VARCHAR(6) NOT NULL, 
	display_name VARCHAR(100) NOT NULL, 
	short_name VARCHAR(10), 
	country VARCHAR(80) NOT NULL, 
	api_team_id INTEGER, 
	PRIMARY KEY (team_id), 
	CONSTRAINT uq_teams_name_gender UNIQUE (team_name, gender), 
	CONSTRAINT ck_teams_gender CHECK (gender IN ('male', 'female'))
);


CREATE TABLE venues (
	venue_id INTEGER NOT NULL, 
	venue_name VARCHAR(160) NOT NULL, 
	city VARCHAR(80) NOT NULL, 
	country VARCHAR(80), 
	capacity INTEGER, 
	api_venue_id INTEGER, 
	PRIMARY KEY (venue_id), 
	CONSTRAINT uq_venues_name_city UNIQUE (venue_name, city), 
	CONSTRAINT ck_venues_capacity CHECK (capacity IS NULL OR capacity > 0)
);


CREATE TABLE players (
	player_id INTEGER NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	cricsheet_id VARCHAR(16), 
	api_player_id INTEGER, 
	team_id INTEGER NOT NULL, 
	gender VARCHAR(6) NOT NULL, 
	playing_role VARCHAR(30) NOT NULL, 
	batting_style VARCHAR(30), 
	bowling_style VARCHAR(40), 
	date_of_birth DATE, 
	is_active BOOLEAN NOT NULL, 
	first_match_date DATE, 
	last_match_date DATE, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (player_id), 
	CONSTRAINT ck_players_role CHECK (playing_role IN ('Batsman', 'Bowler', 'All-rounder', 'Wicket-keeper')), 
	CONSTRAINT ck_players_gender CHECK (gender IN ('male', 'female')), 
	UNIQUE (cricsheet_id), 
	FOREIGN KEY(team_id) REFERENCES teams (team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_players_team_id ON players (team_id);
CREATE INDEX ix_players_name ON players (full_name);
CREATE INDEX ix_players_role ON players (playing_role);

CREATE TABLE matches (
	match_id INTEGER NOT NULL, 
	cricsheet_id VARCHAR(20), 
	api_match_id INTEGER, 
	series_id INTEGER, 
	match_desc VARCHAR(100) NOT NULL, 
	match_format VARCHAR(10) NOT NULL, 
	gender VARCHAR(6) NOT NULL, 
	team1_id INTEGER NOT NULL, 
	team2_id INTEGER NOT NULL, 
	venue_id INTEGER NOT NULL, 
	match_date DATE NOT NULL, 
	end_date DATE, 
	status VARCHAR(12) NOT NULL, 
	toss_winner_id INTEGER, 
	toss_decision VARCHAR(5), 
	winner_id INTEGER, 
	victory_margin INTEGER, 
	victory_type VARCHAR(12), 
	result VARCHAR(10) NOT NULL, 
	dls_method BOOLEAN NOT NULL, 
	player_of_match_id INTEGER, 
	overs_limit INTEGER, 
	match_year INTEGER NOT NULL, 
	match_quarter INTEGER NOT NULL, 
	source VARCHAR(12) NOT NULL, 
	PRIMARY KEY (match_id), 
	CONSTRAINT ck_matches_distinct_teams CHECK (team1_id <> team2_id), 
	CONSTRAINT ck_matches_format CHECK (match_format IN ('Test', 'ODI', 'T20I')), 
	CONSTRAINT ck_matches_gender CHECK (gender IN ('male', 'female')), 
	CONSTRAINT ck_matches_status CHECK (status IN ('Upcoming', 'Live', 'Completed')), 
	CONSTRAINT ck_matches_result CHECK (result IN ('normal', 'tie', 'no result', 'draw')), 
	CONSTRAINT ck_matches_toss CHECK (toss_decision IS NULL OR toss_decision IN ('bat', 'bowl')), 
	CONSTRAINT ck_matches_vtype CHECK (victory_type IS NULL OR victory_type IN ('runs', 'wickets', 'innings', 'super_over', 'bowl_out')), 
	CONSTRAINT ck_matches_margin CHECK (victory_margin IS NULL OR victory_margin >= 0), 
	CONSTRAINT ck_matches_winner CHECK (winner_id IS NULL OR winner_id = team1_id OR winner_id = team2_id), 
	CONSTRAINT ck_matches_quarter CHECK (match_quarter BETWEEN 1 AND 4), 
	UNIQUE (cricsheet_id), 
	UNIQUE (api_match_id), 
	FOREIGN KEY(series_id) REFERENCES series (series_id) ON DELETE SET NULL, 
	FOREIGN KEY(team1_id) REFERENCES teams (team_id) ON DELETE RESTRICT, 
	FOREIGN KEY(team2_id) REFERENCES teams (team_id) ON DELETE RESTRICT, 
	FOREIGN KEY(venue_id) REFERENCES venues (venue_id) ON DELETE RESTRICT, 
	FOREIGN KEY(toss_winner_id) REFERENCES teams (team_id) ON DELETE RESTRICT, 
	FOREIGN KEY(winner_id) REFERENCES teams (team_id) ON DELETE RESTRICT, 
	FOREIGN KEY(player_of_match_id) REFERENCES players (player_id) ON DELETE SET NULL
);

CREATE INDEX ix_matches_status_date ON matches (status, match_date);
CREATE INDEX ix_matches_team1 ON matches (team1_id);
CREATE INDEX ix_matches_venue ON matches (venue_id);
CREATE INDEX ix_matches_series ON matches (series_id);
CREATE INDEX ix_matches_year_quarter ON matches (match_year, match_quarter);
CREATE INDEX ix_matches_team2 ON matches (team2_id);
CREATE INDEX ix_matches_date ON matches (match_date);
CREATE INDEX ix_matches_format_gender ON matches (match_format, gender);
CREATE INDEX ix_matches_winner ON matches (winner_id);

CREATE TABLE player_career_stats (
	player_id INTEGER NOT NULL, 
	match_format VARCHAR(10) NOT NULL, 
	matches INTEGER NOT NULL, 
	innings INTEGER NOT NULL, 
	not_outs INTEGER NOT NULL, 
	runs INTEGER NOT NULL, 
	balls_faced INTEGER NOT NULL, 
	highest_score INTEGER NOT NULL, 
	batting_avg NUMERIC(10, 2) NOT NULL, 
	strike_rate NUMERIC(10, 2) NOT NULL, 
	centuries INTEGER NOT NULL, 
	fifties INTEGER NOT NULL, 
	wickets INTEGER NOT NULL, 
	bowling_avg NUMERIC(10, 2), 
	economy NUMERIC(10, 2), 
	catches INTEGER NOT NULL, 
	stumpings INTEGER NOT NULL, 
	PRIMARY KEY (player_id, match_format), 
	CONSTRAINT ck_career_format CHECK (match_format IN ('Test', 'ODI', 'T20I')), 
	CONSTRAINT ck_career_not_outs CHECK (not_outs <= innings), 
	FOREIGN KEY(player_id) REFERENCES players (player_id) ON DELETE CASCADE
);

CREATE INDEX ix_career_format ON player_career_stats (match_format);

CREATE TABLE batting_performances (
	perf_id INTEGER NOT NULL, 
	match_id INTEGER NOT NULL, 
	innings_no INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	team_id INTEGER NOT NULL, 
	batting_position INTEGER NOT NULL, 
	runs INTEGER NOT NULL, 
	balls_faced INTEGER NOT NULL, 
	fours INTEGER NOT NULL, 
	sixes INTEGER NOT NULL, 
	strike_rate NUMERIC(10, 2), 
	is_out BOOLEAN NOT NULL, 
	dismissal_kind VARCHAR(30), 
	dismissed_by_id INTEGER, 
	dismissal_fielder VARCHAR(100), 
	PRIMARY KEY (perf_id), 
	CONSTRAINT uq_batting_match_innings_player UNIQUE (match_id, innings_no, player_id), 
	CONSTRAINT ck_batting_non_negative CHECK (runs >= 0 AND balls_faced >= 0), 
	CONSTRAINT ck_batting_position CHECK (batting_position >= 1), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (player_id) ON DELETE CASCADE, 
	FOREIGN KEY(team_id) REFERENCES teams (team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_batting_match_innings ON batting_performances (match_id, innings_no, team_id, batting_position);
CREATE INDEX ix_batting_player ON batting_performances (player_id);

CREATE TABLE bowling_performances (
	perf_id INTEGER NOT NULL, 
	match_id INTEGER NOT NULL, 
	innings_no INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	team_id INTEGER NOT NULL, 
	balls_bowled INTEGER NOT NULL, 
	maidens INTEGER NOT NULL, 
	runs_conceded INTEGER NOT NULL, 
	wickets INTEGER NOT NULL, 
	economy NUMERIC(10, 2), 
	wides INTEGER NOT NULL, 
	no_balls INTEGER NOT NULL, 
	PRIMARY KEY (perf_id), 
	CONSTRAINT uq_bowling_match_innings_player UNIQUE (match_id, innings_no, player_id), 
	CONSTRAINT ck_bowling_values CHECK (balls_bowled > 0 AND runs_conceded >= 0 AND wickets BETWEEN 0 AND 10), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (player_id) ON DELETE CASCADE, 
	FOREIGN KEY(team_id) REFERENCES teams (team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_bowling_match ON bowling_performances (match_id);
CREATE INDEX ix_bowling_player ON bowling_performances (player_id);

CREATE TABLE fielding_performances (
	perf_id INTEGER NOT NULL, 
	match_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	team_id INTEGER NOT NULL, 
	catches INTEGER NOT NULL, 
	stumpings INTEGER NOT NULL, 
	run_outs INTEGER NOT NULL, 
	PRIMARY KEY (perf_id), 
	CONSTRAINT uq_fielding_match_player UNIQUE (match_id, player_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (player_id) ON DELETE CASCADE, 
	FOREIGN KEY(team_id) REFERENCES teams (team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_fielding_player ON fielding_performances (player_id);

CREATE TABLE innings (
	innings_id INTEGER NOT NULL, 
	match_id INTEGER NOT NULL, 
	innings_no INTEGER NOT NULL, 
	team_id INTEGER NOT NULL, 
	runs INTEGER NOT NULL, 
	wickets INTEGER NOT NULL, 
	balls INTEGER NOT NULL, 
	extras INTEGER NOT NULL, 
	target_runs INTEGER, 
	declared BOOLEAN NOT NULL, 
	over_runs_json TEXT, 
	fow_json TEXT, 
	PRIMARY KEY (innings_id), 
	CONSTRAINT uq_innings_match_no UNIQUE (match_id, innings_no), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE CASCADE, 
	FOREIGN KEY(team_id) REFERENCES teams (team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_innings_match ON innings (match_id);

CREATE TABLE match_players (
	match_id INTEGER NOT NULL, 
	player_id INTEGER NOT NULL, 
	team_id INTEGER NOT NULL, 
	PRIMARY KEY (match_id, player_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE CASCADE, 
	FOREIGN KEY(player_id) REFERENCES players (player_id) ON DELETE CASCADE, 
	FOREIGN KEY(team_id) REFERENCES teams (team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_match_players_player ON match_players (player_id);

CREATE VIEW vw_match_results AS SELECT m.match_id, m.match_date, m.match_desc, m.match_format, m.gender, m.status, t1.display_name AS team1, t2.display_name AS team2, v.venue_name, v.city, v.country AS venue_country, w.display_name AS winner, m.victory_margin, m.victory_type, m.result, s.series_name FROM matches m JOIN teams t1 ON t1.team_id = m.team1_id JOIN teams t2 ON t2.team_id = m.team2_id JOIN venues v ON v.venue_id = m.venue_id LEFT JOIN teams w ON w.team_id = m.winner_id LEFT JOIN series s ON s.series_id = m.series_id;

CREATE VIEW vw_player_batting_summary AS SELECT p.player_id, p.full_name, p.playing_role, p.gender, t.display_name AS team_name, COUNT(*) AS innings, SUM(b.runs) AS total_runs, ROUND(1.0 * SUM(b.runs) / NULLIF(SUM(CASE WHEN b.is_out THEN 1 ELSE 0 END), 0), 2) AS batting_avg, ROUND(100.0 * SUM(b.runs) / NULLIF(SUM(b.balls_faced), 0), 2) AS strike_rate, MAX(b.runs) AS highest_score FROM batting_performances b JOIN players p ON p.player_id = b.player_id JOIN teams t ON t.team_id = p.team_id GROUP BY p.player_id, p.full_name, p.playing_role, p.gender, t.display_name;
